INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='山西' AND city='大同' LIMIT 1), '阳高县', '采凉山', '\\N', 0.0, 0.0, 0.0, NULL, '采凉山位于大同城东20公里处，古称纥真山、纥干山、采药山。系阴山余脉，海拔2144．6米，为大同之镇山。　该山是一典型的', '山西省大同市阳高县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='山西' AND city='忻州' LIMIT 1), '河曲县', '娘娘滩', '\\N', 3.5, 0.0, 0.0, NULL, '位于河曲县城东北7．5公里的楼子营乡河湾村，在晋、陕和内蒙古三省区交界的黄河之中。民间传说，汉高后吕雉专权，曾将汉文帝的', '山西省忻州市河曲县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='山西' AND city='太原' LIMIT 1), '清徐县', '龙林山', '\\N', 0.0, 0.0, 0.0, NULL, '综观龙林山的景物分布，形成了以梵宇寺为中心的三环格局，以天然柏松林为内环景观，以村庄果园为外环景观', '山西省太原市清徐县马峪乡', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='山西' AND city='大同' LIMIT 1), '大同县', '文嬴湖', '\\N', 3.5, 0.0, 0.0, NULL, '旧称“文莺湖”。背依白登山、采凉山，波澄一镜，湖光山影，竟秀争奇。北魏以来，一直是大同豪门望族、文人墨客游渔抒怀的佳所。', '山西省大同市大同县', NULL, NULL, 3);
