INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='山西' AND city='吕梁' LIMIT 1), '离石区', '凤山道院', '\\N', 3.5, 0.0, 0.0, NULL, '凤山道院位于离石市北的凤山腰间，原名“天真观”。远远望去，“名山仙境”四个石刻大字十分醒目，这是一处风景秀丽，古建别致的', '山西省吕梁市离石区凤山', NULL, NULL, 3);
