INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='酒泉' LIMIT 1), '肃州区', '肃州花城湖生态旅游区', '\\N', 0.0, 0.0, 0.0, NULL, '城市居民休闲娱乐的良好去处', '甘肃省酒泉肃州区花城湖', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='酒泉' LIMIT 1), '阿克塞县', '苏干湖', '\\N', 0.0, 0.0, 0.0, NULL, '位于阿克塞县海子草原西北端，有大苏干湖、小苏干湖两湖。海子草原是一个秀美的盆地草原，草过马背，微风指时碧浪翻滚，确为“风', '甘肃省酒泉阿克塞哈萨克族自治县苏干湖', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='天水' LIMIT 1), '秦州区', '李广墓', '\\N', 3.5, 0.0, 0.0, NULL, '在市区南郊的文山山麓。墓冢高约2米，周长26米，祭庭为3间悬山顶，垣墙大门额题“飞将佳城”。墓碑上镌有“汉将军李广之墓”', '甘肃省天水秦州区李广墓', NULL, NULL, 3);
