INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='临夏' LIMIT 1), '临夏市', '刘家峡恐龙国家地质公园', '\\N', 3.6, 0.0, 0.0, NULL, '甘肃刘家峡恐龙国家地质公园，总面积约十五平方公里。一九九八年八月，经过野外地质勘察发现了国内罕见的恐龙足印化石群。截止目', '甘肃省临夏州临夏市永靖县', NULL, NULL, 3);
