INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='武威' LIMIT 1), '海藏寺', '武威市博物馆', '\\N', 3.5, 0.0, 0.0, NULL, '武威，亦称凉州，地处甘肃省河西走廊东端，历史上曾是丝绸之路的要冲。公元前121年，因汉武帝派骠骑大将军霍去病远征河西，击', '甘肃省武威市凉州区', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='兰州' LIMIT 1), '七里河区', '金天观', '\\N', 3.5, 0.0, 0.0, NULL, '金天观在兰州市七里河西津东路，肃庄王建于明建文一年（1400），占地54亩。在此之前，唐为云峰寺，宋为九阳观。因地处城池', '甘肃省兰州市七里河区华林路1号', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='甘肃' AND city='兰州' LIMIT 1), '城关区', '八盘峡', '\\N', 3.5, 0.0, 0.0, NULL, '这里有雄伟的电站大坝，环境优美的厂区，宽阔的库区水面。厂房内发电机组轰鸣，厂房外树木成荫，百花盛开，鸟语婉转，风景如画。', '甘肃省兰州市城关区', NULL, NULL, 3);
