INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海西蒙古族藏族自治州' LIMIT 1), '天峻县', '鲁芒沟岩画', '\\N', 3.5, 0.0, 0.0, NULL, '位于天峻县天棚乡鲁芒沟内约4公里的东山根，共发现三处。一处在山根北侧，在一块约3平方米的大石块上刻有50多个不同形态的兽', '青海省海西天峻县天棚乡鲁芒沟', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='玉树藏族自治州' LIMIT 1), '治多县', '烟瘴挂大峡谷', '\\N', 3.5, 0.0, 0.0, NULL, '一个美丽又神奇的野生动物天堂', '青海省玉树治多县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='黄南藏族自治州' LIMIT 1), '同仁县', '吾屯寺', '\\N', 0.0, 0.0, 0.0, NULL, '藏族“热贡艺术”的发祥地', '青海省黄南州同仁县隆务河东岸的吾屯村', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海西蒙古族藏族自治州' LIMIT 1), '都兰县', '都兰国际狩猎场', '\\N', 3.6, 0.0, 0.0, NULL, '沟岔曲折，冈峦兀立，晨雾氤氲，溪水潺潺', '海西蒙古族藏族自治州都兰县西南135KM', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海西蒙古族藏族自治州' LIMIT 1), '都兰县', '香加', '\\N', 3.5, 0.0, 0.0, NULL, '在都兰垭口西64公里的地方，有一座小镇叫香日德。从这里弯向南就可进入布尔汗布达山腹地，也是进入巴隆野生动物保护区的一条通', '青海省海西都兰县香日德镇', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海东地区' LIMIT 1), '乐都县', '乐都柳湾墓地', '\\N', 3.6, 0.0, 0.0, NULL, '位于乐都县东17公里柳湾村一带，也称乐都柳湾墓地。总面积11万平方米。按照原始社会不同文化类型的墓葬可分为马家窑文化半山', '青海省海东地区乐都县东柳湾村', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海西蒙古族藏族自治州' LIMIT 1), '', '宗马海湖', '\\N', 0.0, 0.0, 0.0, NULL, '年均气温约1.5℃', '青海省海西蒙古族藏族自治州柴达木盆地北缘马海盆地内', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='果洛藏族自治州' LIMIT 1), '甘德县', '多卡寺', '\\N', 0.0, 0.0, 0.0, NULL, '藏传佛教宁玛、格鲁合一的无偏教法圣地', '青海省果洛洲甘德县境内东吉乡的东吉滩', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海西蒙古族藏族自治州' LIMIT 1), '天峻县', '卢山岩画', '\\N', 3.5, 0.0, 0.0, NULL, '位于天峻县东部江河乡卢山山丘的30多块花岗长粉岩上，计270多幅各类图画。画面内容包括牛、鹿、马、鹰、豹子、狗等动物形象', '青海省海西州天峻县江河乡的南山北麓', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='海西蒙古族藏族自治州' LIMIT 1), '格尔木市', 'Node星球818戈壁嘉年华', '\\N', 0.0, 0.0, 0.0, NULL, 'NODE星球·昆仑文化旅游节818戈壁极限嘉年华是一次大型的徒步文旅活动，届时，圣洁的昆仑山脚下将蔓延开NODE星球的属', '大巴发车地点：格尔木盐湖广场、奥林匹克广场、盐湖酒店、中浩希尔顿逸林酒店。活动地点：格尔木市无人区戈壁', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='玉树藏族自治州' LIMIT 1), '治多县', '楚玛尔河', '\\N', 0.0, 0.0, 0.0, NULL, '横卧江源北部，汇集昆仑山来水汇入通天河', '青海省玉树藏族自治州治多县', NULL, NULL, 3);
