INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='青海' AND city='黄南藏族自治州' LIMIT 1), '同仁县', '热贡艺术乡', '\\N', 3.6, 0.0, 0.0, NULL, '五屯艺术，是藏族佛教领域中的一个重要流派，是我省黄南藏族自治州同仁县五屯地区民间艺人在长达五、六个世纪的艺术实践中，共同', '青海省黄南藏族自治州同仁县五屯地区', NULL, NULL, 3);
