INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='内蒙古' AND city='呼和浩特' LIMIT 1), '赛罕区', '万部华严经塔', '\\N', 3.8, 0.0, 0.0, NULL, '俗称白塔。约建于辽圣宗时（983一1031年在位），历代都曾维修。近年又经修缮，恢复了塔刹，清理出淤埋地下的基座。塔为楼', '内蒙古呼和浩特市东郊白塔村西南方', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='内蒙古' AND city='呼和浩特' LIMIT 1), '玉泉区', '金刚座舍利宝塔', '\\N', 3.7, 0.0, 0.0, NULL, '寺宇早就损毁，惟此宝塔巍然屹立', '呼和浩特市旧城五塔寺街', NULL, NULL, 3);
