INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='内蒙古' AND city='呼伦贝尔' LIMIT 1), '海拉尔区', '典型草原', '\\N', 3.7, 0.0, 0.0, NULL, '又称高平原草原，约占呼伦贝尔草原总面积的30%，地势平坦，一望无垠。主要草种有硷草、针茅、冰草，牧草质量高。', '内蒙古自治区呼伦贝尔市海拉尔区北国经典小区', NULL, NULL, 3);
