INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='内蒙古' AND city='呼和浩特' LIMIT 1), '武川县', '乌素图国家森林公园', '3A景区', 3.6, 0.0, 0.0, NULL, '呼和浩特市北郊是峰峦叠翠、绵亘数百里的大青山，在呼和浩特市辖区内的山麓便是乌素图国家森林公园。森林公园方圆60平方公里，', '内蒙古省呼和浩特市玉泉区五塔寺后街48号', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='内蒙古' AND city='通辽' LIMIT 1), '', '科尔沁博物馆', '3A景区', 0.0, 0.0, 0.0, NULL, '科尔沁博物馆的前身为哲盟博物馆，创立于1975年，2003年10月迁入新址，并更名为科尔沁博物馆。为全额拨款的事业单位。', '内蒙古通辽市科尔沁区霍林河大街文化体育广场北侧', NULL, NULL, 3);
