INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '城关区', '仓姑寺', '\\N', 3.5, 0.0, 0.0, NULL, '拉萨著名的尼姑寺仓姑寺始建於明代，距今有五百多年的历史，创建人为宗喀巴大师的弟子古觉群丹。古觉群丹生於藏历第六铙迥土鼠年', '西藏拉萨市城关区林廓路上段', NULL, NULL, 3);
