INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '林芝县', '布久喇嘛林寺', '\\N', 3.5, 0.0, 0.0, NULL, '该寺依山傍水，佛殿庭院掩映绿荫之中，院内藏犬成群。整个寺院形状内呈正四角，外底层屋檐共有二十角，第二到第三层屋檐为八角，', '西藏林芝县尼洋河下游左岸', NULL, NULL, 3);
