INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '', '西藏大学', '\\N', 0.0, 0.0, 0.0, NULL, '由原西藏大学和原西藏农牧学院于2001年合并组建而成。合并前的两所学校都有着光荣的历史和传统。时至今日，西藏大学是国家“', '西藏自治区拉萨市江苏路36号', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '城关区', '琉璃桥', '\\N', 0.0, 0.0, 0.0, NULL, '自治区级文物保护单位。拉萨著名的交通津梁。又名“宇妥桥”，藏语称“宇妥桑巴”，即“绿松石桥”。位于大昭寺西，宇拓路中段。', '西藏自治区拉萨市城关区', NULL, NULL, 3);
