INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '当雄县', '当雄赛马场', '\\N', 0.0, 48.0, 95.0, NULL, '当雄赛马场地处阿热湿地，这是一个集阿热湿地观光、羌塘唐拉民俗文化演艺、马术表演、“当吉仁”赛马节、草原特色旅游产品销售、', '拉萨市当雄县曲卡镇', NULL, NULL, 3);
