INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '日喀则市', '曲典尼玛尼姑庵', '\\N', 0.0, 0.0, 0.0, NULL, '相传，长时间站在湖边，可从湖中看到自己死后的脱生之地。信教群众把自己珍惜的东西投入湖中以祈祷来世幸福。离“观相湖”半公里', '西藏日喀则市', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='昌都' LIMIT 1), '芒康县', '西藏格林丹东温泉酒店', '\\N', 0.0, 0.0, 0.0, NULL, '酒店温泉地处西藏芒康县曲孜卡乡政府境内，面对滔滔的澜沧江。在这里可游览别具一格、素有“西藏江南”之称的田园风光，给人一种', '西藏自治区昌都地区芒康县曲孜卡乡温泉度假区', NULL, NULL, 3);
