INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '林芝县', '东久自然保护区', '\\N', 3.5, 0.0, 0.0, NULL, '保护区以保护赤斑羚等野生动物和它们生存所需的特定环境为目的，这里山高谷深，水流湍急，森林茂密，冰峰雪岭互相辉映，溪流瀑布', '西藏林芝市林芝县东久自然保护区', NULL, NULL, 3);
