INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='昌都' LIMIT 1), '察雅县', '仁达摩崖造像', '\\N', 3.5, 0.0, 0.0, NULL, '仁达摩崖造像位于察雅县旺布乡境内丹玛山崖。当地群众依据造像而称之为仁达大日如来殿。造像利用丹玛山峭壁岩石依山雕凿而成。分', '察雅县旺布乡境内丹玛山崖', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='那曲' LIMIT 1), '比如', '达木寺', '\\N', 0.0, 0.0, 0.0, NULL, '著名而神秘的骷髅墙位于西藏那曲地区的比如县茶曲乡的达木寺内。达木寺是建在一个不高的山岗上，骷髅墙砌在寺院的一个门也上了锁', '西藏那曲地区比如县茶曲乡', NULL, NULL, 3);
