INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '日喀则市', '马卡鲁峰', '\\N', 3.6, 0.0, 0.0, NULL, '海拔8463米，位于喜马拉雅山脉中段，其西北方向距珠穆朗玛峰24公里，沿西北--东南山脊为界，北侧在中国西藏境内，南侧在', '西藏日喀则市', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '日喀则市', '宁金抗沙峰', '\\N', 3.6, 0.0, 0.0, NULL, '宁金抗沙峰在雅鲁藏布江之南，喜玛拉雅山以北，有一条延伸360多公里的山脉，藏族人民把它叫做拉轨岗日山。拉轨岗日山的东面是', '在雅鲁藏布江之南，喜玛拉雅山以北', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='阿里' LIMIT 1), '扎达县', '东嘎皮央', '\\N', 3.5, 0.0, 0.0, NULL, '这是在1992年才被发现的石窟壁画遗址，位于扎达以北40公里处。东嘎是扎达县的一个靠山临水，只有十几户人家的小村庄，在“', '扎达以北40公里处', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='昌都' LIMIT 1), '昌都县', '谷布神山', '\\N', 3.5, 0.0, 0.0, NULL, '登上峰顶，群山尽收眼底，“一览众山小”', '西藏昌都县日通乡与如意乡交界处', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='山南' LIMIT 1), '琼结县', '藏王墓', '\\N', 3.7, 0.0, 0.0, NULL, '松赞干布和文成公主都长眠于此。藏王墓位于西藏山南地区琼结县境内，是吐蕃王朝时期第29代赞普至第40代（末代）赞普、大臣及', '西藏山南地区琼结县境内', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='山南' LIMIT 1), '扎囊县', '囊色林庄园', '\\N', 3.5, 0.0, 0.0, NULL, '位于扎囊县扎囊乡，与桑耶寺隔江相望，距泽当镇25公里。该庄园是现今西藏保存较为完整的古老贵族庄园，属山南地区重点文物保护', '西藏扎囊县扎囊乡', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '苯日神山', '苯日神山漂流', '\\N', 0.0, 0.0, 0.0, NULL, '征服西藏，征服苯日神山漂流', '西藏省林芝林芝县驻地普拢的东南方苯日神山内', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '城关区', '木如寺印经院', '\\N', 3.6, 0.0, 0.0, NULL, '西藏目前仅有的一家佛经印刷厂', '西藏拉萨市城关区北京东路13号', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '日喀则市', '南尼寺', '\\N', 3.5, 0.0, 0.0, NULL, '在日喀则康马县境内北部，距江孜县城12公里。建于吐蕃王朝时期，距今已有1200多年的历史。该寺曾信奉过宁玛派、噶当派，现', '西藏日喀则地区康马县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='山南' LIMIT 1), '桑日县', '恰嘎曲德寺', '\\N', 3.5, 0.0, 0.0, NULL, '占地面积2000平方米，建于16世纪末，属格鲁派。为受第三世达赖喇嘛旨意而兴建的格鲁派寺院。寺内壁画众多，题材广泛。现僧', '西藏山南桑日县绒乡境内', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '拉孜县', '觉囊寺', '\\N', 3.5, 0.0, 0.0, NULL, '历史悠久，建有一座“万佛一见得解塔”', '西藏拉萨日喀则拉孜县欧布琼山山腰处', NULL, NULL, 3);
