INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '林芝县', '德木寺遗址', '\\N', 0.0, 0.0, 0.0, NULL, '德木寺是西藏历史上一个重要的文化符号，鲁朗这个名称也与其息息相关。四世德木活佛与五世达赖喇嘛进京，五世达赖经过这个地方的', '西藏林芝地区林芝县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '林芝县', '茶园生态旅游区', '\\N', 3.5, 0.0, 0.0, NULL, '该区包括通麦、易贡、八盖三乡，主要景观有茶园、铁山、易贡湖、寺庙、“十勇士纪念碑”等。该区茶园广阔茂盛，森林茂密、环境清', '西藏林芝县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='山南' LIMIT 1), '贡嘎县', '多吉扎寺', '\\N', 3.5, 0.0, 0.0, NULL, '16世纪末叶由藏传佛教宁玛派（红教）僧人扎西道杰兴建，为宁玛派在西藏的重要寺院之一，与敏珠林寺齐名。清康熙五十七年（17', '贡嘎县雅鲁藏布江北岸', NULL, NULL, 3);
