INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='昌都' LIMIT 1), '江达县', '生钦朗扎山', '\\N', 3.6, 0.0, 0.0, NULL, '生钦郎扎神山是康区二十五座佛教神山之一。生钦郎扎神山规模较大，骑马转一圈需一天的时间。按照传统的说法，该山约有几十个参观', '西藏昌都市江达县', NULL, NULL, 3);
