INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='宁夏' AND city='固原' LIMIT 1), '彭阳县', '五峰山', '\\N', 3.5, 0.0, 0.0, NULL, '五峰山，海拔1523米，山势奇特，中分五指，故名。位于彭阳县城东16公里处的城阳乡韩寨村。北依长城塬，南濒茹河，西临深涧', '彭阳县城阳乡韩寨村', NULL, NULL, 3);
