INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='宁夏' AND city='吴忠' LIMIT 1), '利通区', '中营堡湖', '\\N', 0.0, 0.0, 0.0, NULL, '中营堡湖位于市区西南，距市区15公里。旧时曾是一座“兵堡”，现存遗址。湖乃“宁夏七十二连湖”之一，是吴忠现存水域面积较大', '宁夏吴忠市利通区马家湖卫生院北300米', NULL, NULL, 3);
