INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='新疆' AND city='博尔塔拉' LIMIT 1), '精河县', '艾比湖湿地', '\\N', 0.0, 0.0, 0.0, NULL, '古尔班通古特沙漠的西缘，有着日映波光、月落青萍的鸟类王国——艾比湖。——艾比湖，蒙语意为“向阳之湖”，艾比湖水面面积61', '新疆博尔塔拉博乐市', NULL, NULL, 3);
