INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '墨脱县', '解放大桥', '\\N', 0.0, 0.0, 0.0, NULL, '解放大桥位于背崩乡，横跨雅鲁藏布江。作为雅鲁藏布江上的一座重要桥梁，解放大桥是连接墨脱县与外界的咽喉，从这里往下不远就是', '西藏自治区林芝地区墨脱县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '南木林县', '色吾沟', '\\N', 3.5, 0.0, 0.0, NULL, '地处日喀则南木林县拉布普乡、海拔4500米。这里景色秀美，遍野灌木花草，周围山峰形态各异，千姿百态。色吾沟是高僧修行成道', '西藏日喀则地区南木林县拉布普乡', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '工布江达县', '阿沛村', '\\N', 0.0, 0.0, 0.0, NULL, '阿沛民俗文化村原为旧西藏十二大庄园之一的阿沛庄园所在地。17世纪，阿沛家族以世袭贵族身份开始在江达定居。历代阿沛多为噶伦', '西藏>林芝>工布江达县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '城关区', '旭日牧区生态民俗园', '3A景区', 0.0, 0.0, 0.0, NULL, '旭日牧区民俗园坐落于从拉萨市区去贡嘎机场的路边，距离拉萨市区大约15公里。从外面就可以一窥民俗园庞大的规模，民俗园大门的', '西藏拉萨市堆龙德庆县机场路旭日度假村', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '墨脱县', '仁钦崩寺', '\\N', 0.0, 0.0, 0.0, NULL, '位于墨脱村南则玛拉山上。建仁钦崩寺时间是在门巴东迁后不久，距今约8代人。据传是由甘布寺中的活佛甘布建筑的12面墙和东西南', '西藏林芝地区墨脱县墨脱村南则玛拉山上', NULL, NULL, 3);
