INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='新疆' AND city='伊犁' LIMIT 1), '霍城县', '秃黑鲁克帖木尔汗麻扎', '\\N', 4.0, 0.0, 0.0, NULL, '秃黑鲁克帖木尔汗是成吉思汗第七世孙，是一位富于传奇色彩的察合台后王。公元1346年，年仅16岁的秃黑鲁克帖木尔被拥立为蒙', '伊犁哈萨克自治州霍城县', NULL, NULL, 3);
