INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '墨脱县', '老虎嘴瀑布', '\\N', 0.0, 0.0, 0.0, NULL, '凌空而泻的瀑布，象银河倒悬，坠至半空，忽被峭石拦腰斩断，刹时雪浪飞溅，宛如千万串断线的珍珠，纷纷扬扬，沿悬立千纫的绝壁陡', '西藏林芝地区墨脱县', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '波密县', '岗云杉林', '\\N', 0.0, 0.0, 0.0, NULL, '山高树密，古木参天，珍稀野生动物活动频繁', '西藏林芝波密县扎木镇', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='林芝' LIMIT 1), '工布江达县', '太昭古城', '\\N', 0.0, 0.0, 0.0, NULL, '在莽原和雪山脚下，清澈的尼洋河边，巍峨的群山怀抱，有一座历经千年沧桑的小镇，它的名字叫“太昭”。每次从拉萨到林芝，翻越米', '西藏林芝市工布江达县太昭村', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='日喀则' LIMIT 1), '日喀则市', '贡觉林卡', '\\N', 3.5, 0.0, 0.0, NULL, '古园林建筑。又名重觉林宫，位于城东，由七世班禅丹白尼玛于1825年兴建。建城后名为德吉（幸福）经堂。后因清道光皇帝御回用', '西藏日喀则市东面约2公里处的年楚河畔', NULL, NULL, 3);
INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '墨竹工卡县', '直贡噶举派寺庙群', '\\N', 3.5, 0.0, 0.0, NULL, '拉萨以东墨竹工卡县境内雪绒河边，伫立着一座连着一座的直贡噶举派寺院。据说历史上曾经有30处之多，按藏文30个字母系列排列', '西藏拉萨墨竹工卡县境内雪绒河边', NULL, NULL, 3);
