INSERT INTO scenic_spot (city_id, district, spot_name, spot_type, score, ticket_price, sales_volume, coordinate, spot_intro, address, longitude, latitude, star_level) VALUES ((SELECT id FROM scenic_city WHERE province='西藏' AND city='拉萨' LIMIT 1), '羊八井镇', '羊八井寺', '\\N', 0.0, 0.0, 0.0, NULL, '羊八井寺，在拉萨市之当雄县境内，位于县驻地面南的羊八井镇。羊八井镇距拉萨93公里。羊八井（梵音译作毗舍厘或毗萨尔，意为广', '西藏自治区拉萨市当雄县羊八井镇', NULL, NULL, 3);
